package app.beingmuslim.android.citycatalog

import java.text.Normalizer
import java.util.Locale

/**
 * The offline city catalog: a country → city list with coordinates and IANA
 * timezones, parsed from the asset generated by `tools/build-city-catalog.py`
 * and bundled with the app (`GLOSSARY.md`, *City catalog*).
 *
 * The catalog holds no UI, location, notification, or networking imports: it is
 * pure data and lookup, and is expected to be loaded once and shared.
 *
 * Cities are held in the order the asset supplies them — most populated first —
 * so that [search] returns the most significant place first.
 *
 * The asset format is documented in `docs/CITY_CATALOG.md`:
 *
 * ```
 * # id  name  bengali_name  latitude  longitude  country_code  timezone
 * ```
 */
class CityCatalog private constructor(
    private val cities: List<City>,
    private val nameKeys: List<String>,
    private val bengaliKeys: List<String?>,
) {

    private val byId: Map<Long, City> = cities.associateBy(City::id)

    /**
     * Every city, in catalog order. Exposed for whole-catalog checks — the
     * bundled asset is validated through it — and for the tests; the app itself
     * looks cities up with [byId] and [search].
     */
    fun all(): List<City> = cities

    /** The city with [id], or null when the catalog does not contain it. */
    fun byId(id: Long): City? = byId[id]

    /**
     * Cities whose English or Bengali name matches [query], most significant
     * first, with names that start with the query ranked ahead of names that
     * merely contain it.
     *
     * The match is case-insensitive and ignores diacritics in Latin names. A
     * blank query matches nothing. At most [limit] cities are returned.
     */
    fun search(query: String, limit: Int = DEFAULT_SEARCH_LIMIT): List<City> {
        require(limit > 0) { "limit must be positive, was $limit" }
        val key = normalize(query)
        if (key.isEmpty()) return emptyList()

        val startsWith = ArrayList<City>()
        val contains = ArrayList<City>()
        for (index in cities.indices) {
            // Prefix matches outrank substring matches, so the only safe early
            // exit is having enough of them; scanning must otherwise continue so
            // a prefix match ranked later still displaces a substring match.
            if (startsWith.size >= limit) break

            if (nameKeys[index].startsWith(key) || bengaliKeys[index]?.startsWith(key) == true) {
                startsWith += cities[index]
            } else if (contains.size < limit &&
                (nameKeys[index].contains(key) || bengaliKeys[index]?.contains(key) == true)
            ) {
                contains += cities[index]
            }
        }
        return (startsWith + contains).take(limit)
    }

    companion object {
        /** How many cities [search] returns by default. */
        const val DEFAULT_SEARCH_LIMIT = 20

        private const val COLUMN_COUNT = 7
        private val COMBINING_MARKS = Regex("\\p{Mn}+")
        private val BENGALI = Regex("[\u0980-\u09FF]")

        /**
         * Parses the catalog asset's [lines]. Lines that are blank or start with
         * `#` are ignored; a line with the wrong number of columns is a corrupt
         * asset and fails fast.
         */
        fun parse(lines: Sequence<String>): CityCatalog {
            val cities = ArrayList<City>()
            lines.forEachIndexed { index, line ->
                if (line.isBlank() || line.startsWith('#')) return@forEachIndexed
                val columns = line.split('\t')
                require(columns.size == COLUMN_COUNT) {
                    "city catalog line ${index + 1}: expected $COLUMN_COUNT columns, " +
                        "got ${columns.size}"
                }
                cities += City(
                    id = columns[0].toLong(),
                    name = columns[1],
                    bengaliName = columns[2].ifEmpty { null },
                    latitude = columns[3].toDouble(),
                    longitude = columns[4].toDouble(),
                    countryCode = columns[5],
                    timezone = columns[6],
                )
            }
            return CityCatalog(
                cities = cities,
                nameKeys = cities.map { normalize(it.name) },
                bengaliKeys = cities.map { it.bengaliName?.let(::normalize) },
            )
        }

        /**
         * Lower-cases and trims for case-insensitive matching, and folds
         * diacritics so that, for example, `Dohār` matches `dohar`.
         *
         * Diacritic folding is applied to Latin names only: many Bengali vowel
         * signs and the virama are combining marks that carry meaning, so the
         * Bengali script is matched as written.
         */
        private fun normalize(value: String): String {
            val trimmed = value.trim().lowercase(Locale.ROOT)
            if (BENGALI.containsMatchIn(trimmed)) return trimmed
            return Normalizer.normalize(trimmed, Normalizer.Form.NFD).replace(COMBINING_MARKS, "")
        }
    }
}
